/* ML-DSA Sign KAT structure */
typedef struct {
    const Ipp8u* message;
    Ipp32s msg_len;
    const Ipp8u* private_key;
    const Ipp8u* expected_signature;
    Ipp32u sig_len;
    const Ipp8u* rng_seed;
} MLDSASignKAT;

static const MLDSASignKAT sign_kat_vectors[] = {
  /* test signature */
    {sigver_message_1,
     sizeof(sigver_message_1),
     sigver_private_key_1, sigver_signature_1,
     sizeof(sigver_signature_1),
     sigver_seed},
 /* test z_max rejection */
    {sigver_message_2,
     sizeof(sigver_message_2),
     sigver_private_key_1, sigver_signature_2,
     sizeof(sigver_signature_2),
     sigver_seed},
 /* test r0_max rejection */
    {sigver_message_3,
     sizeof(sigver_message_3),
     sigver_private_key_1, sigver_signature_3,
     sizeof(sigver_signature_3),
     sigver_seed},
 /* test h_ones rejection */
    {sigver_message_4,
     sizeof(sigver_message_4),
     sigver_private_key_1, sigver_signature_4,
     sizeof(sigver_signature_4),
     sigver_seed},
 /* test ct0 rejection */
    {sigver_message_5,
     sizeof(sigver_message_5),
     sigver_private_key_2, sigver_signature_5,
     sizeof(sigver_signature_5),
     sigver_seed}
};

/* ML-DSA Verify KAT structure */
typedef struct {
    const Ipp8u* message;
    Ipp32s msg_len;
    const Ipp8u* public_key;
    const Ipp8u* signature;
    Ipp32u sig_len;
} MLDSAVerifyKAT;

static const MLDSAVerifyKAT verify_kat_vectors[] = {
    {sigver_message_1,
     sizeof(sigver_message_1),
     sigver_public_key_1, sigver_signature_1,
     sizeof(sigver_signature_1)}
};

